// @ts-nocheck
// GENERATED by `npm run sync:voice` from src/voice/bn.js. Edit the source, not this copy.
// Small, dependency-free helpers for the voice brain. Pure functions, no browser APIs, so the same file
// runs in the app, in Node tests, and (copied by `npm run sync:voice`) inside services/voice-agent.

const BN = '০১২৩৪৫৬৭৮৯';
export const bnDigits = (s) => String(s).replace(/[0-9]/g, (d) => BN[d]);
export const enDigits = (s) => String(s).replace(/[০-৯]/g, (d) => String(BN.indexOf(d)));

// Speech recognisers return Bangla in more than one Unicode spelling (য় as one letter or two, ZWJ/ZWNJ noise,
// punctuation, Bangla vs. Western digits). `fold` makes a transcript and a keyword comparable.
export const fold = (s) =>
  enDigits(String(s ?? ''))
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u200c\u200d]/g, '')
    .replace(/[।,.!?;:"'“”‘’()\[\]{}\-–—_/\\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

export const foldAll = (list) => list.map(fold);

// Longest keyword found in `text` (already folded); 0 when none matches.
// Very short keywords (3 characters or fewer, e.g. "দাম", "গম", "সার") must start a word, otherwise "বাদামি" would
// match "দাম" (price) and "আগমন" would match "গম" (wheat). Longer keywords match anywhere, so suffixes still work
// ("টমেটোর", "সেচের").
const startsWord = (text, k) => text.startsWith(k) || text.includes(` ${k}`);
export function bestHit(text, folded) {
  let best = 0;
  for (const k of folded) {
    if (!k || k.length <= best) continue;
    if (k.length <= 3 ? startsWord(text, k) : text.includes(k)) best = k.length;
  }
  return best;
}
export const hasAny = (text, folded) => bestHit(text, folded) > 0;
export const tokens = (text) => text.split(' ').filter(Boolean);

// Pick the language of a reply. `T(bn, en)` is the same idea as the app's own T().
export const makeT = (lang) => (bn, en) => (lang === 'bn' ? bn : en);

// "১, ২ ও ৩" / "1, 2 and 3"
export function joinList(items, lang) {
  const a = items.filter(Boolean);
  if (a.length <= 1) return a.join('');
  const last = a[a.length - 1];
  return `${a.slice(0, -1).join(', ')} ${lang === 'bn' ? 'ও' : 'and'} ${last}`;
}

export const num = (n, lang, dp = 0) => {
  if (n === null || n === undefined || Number.isNaN(n)) return '–';
  const s = Number(n).toLocaleString('en-IN', { maximumFractionDigits: dp, minimumFractionDigits: 0 });
  return lang === 'bn' ? bnDigits(s) : s;
};

// A spoken line must never carry markdown, bullets or stray symbols into a text-to-speech engine.
export const speakable = (s) =>
  String(s ?? '')
    .replace(/[*_#`>|~]/g, '')
    .replace(/^\s*[-•·]\s+/gm, '')
    .replace(/\s*\n+\s*/g, '। ')
    .replace(/।\s*।/g, '।')
    .replace(/\s{2,}/g, ' ')
    .trim();
